132	 * @publicApi
133	 */
134	export class FastifyAdapter<
135	  TServer extends RawServerBase = RawServerDefault,
136	  TRawRequest extends FastifyRawRequest<TServer> = FastifyRawRequest<TServer>,
137	  TRawResponse extends RawReplyDefaultExpression<TServer> =
138	    RawReplyDefaultExpression<TServer>,
139	  TRequest extends FastifyRequest<
140	    RequestGenericInterface,
141	    TServer,
142	    TRawRequest
143	  > = FastifyRequest<RequestGenericInterface, TServer, TRawRequest>,
144	  TReply extends FastifyReply<
145	    RouteGenericInterface,
146	    TServer,
147	    TRawRequest,
148	    TRawResponse
149	  > = FastifyReply<RouteGenericInterface, TServer, TRawRequest, TRawResponse>,
150	  TInstance extends FastifyInstance<TServer, TRawRequest, TRawResponse> =
151	    FastifyInstance<TServer, TRawRequest, TRawResponse>,
152	> extends AbstractHttpAdapter<TServer, TRequest, TReply> {
153	  protected readonly logger = new Logger(FastifyAdapter.name);
154	  declare protected readonly instance: TInstance;
155	  protected _pathPrefix?: string;
156	
157	  private _isParserRegistered: boolean;
158	  private onRequestHook?: (
159	    request: TRequest,
160	    reply: TReply,
161	    done: (err?: Error) => void,
162	  ) => void | Promise<void>;
163	  private onResponseHook?: (
164	    request: TRequest,
165	    reply: TReply,
166	    done: (err?: Error) => void,
167	  ) => void | Promise<void>;
168	  private isMiddieRegistered: boolean;
169	  private pendingMiddlewares: Array<{ args: any[] }> = [];
170	  private versioningOptions?: VersioningOptions;
171	  private isShuttingDown = false;
172	  private closePromise?: Promise<void>;
173	  private readonly versionConstraint = {
174	    name: 'version',
175	    validate(value: unknown) {
176	      if (!isString(value) && !Array.isArray(value)) {
177	        throw new Error(
178	          'Version constraint should be a string or an array of strings.',
179	        );
180	      }
181	    },
182	    storage() {
183	      const versions = new Map<string, unknown>();
184	      return {
185	        get(version: string | Array<string>) {
186	          if (Array.isArray(version)) {
187	            return versions.get(version.find(v => versions.has(v))!) || null;
188	          }
189	          return versions.get(version) || null;
190	        },
191	        set(versionOrVersions: string | Array<string>, store: unknown) {
192	          const storeVersionConstraint = (version: string) =>
193	            versions.set(version, store);
194	          if (Array.isArray(versionOrVersions))
195	            versionOrVersions.forEach(storeVersionConstraint);
196	          else storeVersionConstraint(versionOrVersions);
197	        },
198	        del(version: string | Array<string>) {
199	          if (Array.isArray(version)) {
200	            version.forEach(v => versions.delete(v));
201	          } else {
202	            versions.delete(version);
203	          }
204	        },
205	        empty() {
206	          versions.clear();
207	        },
208	      };
209	    },
210	    deriveConstraint: (req: FastifyRequest) => {
211	      // Media Type (Accept Header) Versioning Handler
212	      if (this.versioningOptions?.type === VersioningType.MEDIA_TYPE) {
213	        const MEDIA_TYPE_HEADER = 'Accept';
214	        const acceptHeaderValue: string | undefined = (req.headers?.[
215	          MEDIA_TYPE_HEADER
216	        ] || req.headers?.[MEDIA_TYPE_HEADER.toLowerCase()]) as string;
217	
218	        const acceptHeaderVersionParameter = acceptHeaderValue
219	          ? acceptHeaderValue.split(';')[1]
220	          : undefined;
221	
222	        return isUndefined(acceptHeaderVersionParameter)
223	          ? VERSION_NEUTRAL // No version was supplied
224	          : acceptHeaderVersionParameter.split(this.versioningOptions.key)[1];
225	      }
226	      // Header Versioning Handler
227	      else if (this.versioningOptions?.type === VersioningType.HEADER) {
228	        const customHeaderVersionParameter: string | string[] | undefined =
229	          req.headers?.[this.versioningOptions.header] ||
230	          req.headers?.[this.versioningOptions.header.toLowerCase()];
231	
232	        return isUndefined(customHeaderVersionParameter)
233	          ? VERSION_NEUTRAL // No version was supplied
234	          : customHeaderVersionParameter;
235	      }
236	      // Custom Versioning Handler
237	      else if (this.versioningOptions?.type === VersioningType.CUSTOM) {
238	        return this.versioningOptions.extractor(req);
239	      }
240	      return undefined;
241	    },
242	    mustMatchWhenDerived: false,
243	  };
