249	  constructor(
250	    instanceOrOptions?:
251	      | TInstance
252	      | FastifyHttp2Options<any>
253	      | FastifyHttp2SecureOptions<any>
254	      | FastifyHttpsOptions<any>
255	      | FastifyHttpOptions<any>
256	      | FastifyAdapterBaseOptions<TServer>,
257	  ) {
258	    super();
259	
260	    const instance =
261	      instanceOrOptions && (instanceOrOptions as TInstance).server
262	        ? instanceOrOptions
263	        : fastify({
264	            ...(instanceOrOptions as FastifyServerOptions),
265	            routerOptions: {
266	              ...this.getTopLevelRouterOptions(
267	                instanceOrOptions as FastifyServerOptions,
268	              ),
269	              ...(instanceOrOptions as FastifyServerOptions)?.routerOptions,
270	              constraints: {
271	                version: this.versionConstraint as any,
272	              },
273	            },
274	          });
275	
276	    this.setInstance(instance);
277	
278	    if ((instanceOrOptions as FastifyAdapterBaseOptions)?.skipMiddie) {
279	      this.isMiddieRegistered = true;
280	    }
281	
282	    this.instance.addHook('onRequest', (request, reply, done) => {
283	      if (this.onRequestHook) {
284	        this.onRequestHook(request as TRequest, reply as TReply, done);
285	      } else {
286	        done();
287	      }
288	    });
289	
290	    this.instance.addHook('onResponse', (request, reply, done) => {
291	      if (this.onResponseHook) {
292	        this.onResponseHook(request as TRequest, reply as TReply, done);
293	      } else {
294	        done();
295	      }
296	    });
297	  }
