319	  public async init() {
320	    if (this.isMiddieRegistered) {
321	      return;
322	    }
323	    await this.registerMiddie();
324	
325	    // Register any pending middlewares that were added before init
326	    if (this.pendingMiddlewares.length > 0) {
327	      for (const { args } of this.pendingMiddlewares) {
328	        (this.instance.use as any)(...args);
329	      }
330	      this.pendingMiddlewares = [];
331	    }
332	  }
