340	  public listen(
341	    listenOptions: string | number | FastifyListenOptions,
342	    ...args: any[]
343	  ): void {
344	    const isFirstArgTypeofFunction = typeof args[0] === 'function';
345	    const callback = isFirstArgTypeofFunction ? args[0] : args[1];
346	
347	    let options: Record<string, any>;
348	    if (
349	      typeof listenOptions === 'object' &&
350	      (listenOptions.host !== undefined ||
351	        listenOptions.port !== undefined ||
352	        listenOptions.path !== undefined)
353	    ) {
354	      // First parameter is an object with a path, port and/or host attributes
355	      options = listenOptions;
356	    } else {
357	      options = {
358	        port: +listenOptions,
359	      };
360	    }
361	    if (!isFirstArgTypeofFunction) {
362	      options.host = args[0];
363	    }
364	    return this.instance.listen(options, callback);
365	  }
