431	  public applyVersionFilter(
432	    handler: Function,
433	    version: VersionValue,
434	    versioningOptions: VersioningOptions,
435	  ): VersionedRoute<TRequest, TReply> {
436	    if (!this.versioningOptions) {
437	      this.versioningOptions = versioningOptions;
438	    }
439	    const versionedRoute = handler as VersionedRoute<TRequest, TReply>;
440	    versionedRoute.version = version;
441	    return versionedRoute;
