626	  public appendHeader(response: any, name: string, value: string) {
627	    const current = response.getHeader(name);
628	    if (current === undefined) {
629	      return response.header(name, value);
630	    }
631	    // Fastify Reply.header() already concatenates set-cookie.
632	    // Re-passing the accumulated list would duplicate previous cookies.
633	    if (String(name).toLowerCase() === 'set-cookie') {
634	      return response.header(name, value);
635	    }
636	    const values = Array.isArray(current) ? current : [current];
637	    return response.header(name, values.concat(value));
638	  }
