663	  public registerParserMiddleware(prefix?: string, rawBody?: boolean) {
664	    if (this._isParserRegistered) {
665	      return;
666	    }
667	
668	    this.registerUrlencodedContentParser(rawBody);
669	    this.registerJsonContentParser(rawBody);
670	
671	    this._isParserRegistered = true;
672	    this._pathPrefix = prefix
673	      ? !prefix.startsWith('/')
674	        ? `/${prefix}`
675	        : prefix
676	      : undefined;
677	  }
