import {
  Controller,
  Get,
  INestApplication,
  Module,
  NotFoundException,
} from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';

const rawRequest = (
  port: number,
  path: string,
  agent?: http.Agent,
): Promise<{ status: number; headers: http.IncomingHttpHeaders; body: string }> =>
  new Promise((resolve, reject) => {
    http
      .get(
        `http://localhost:${port}${path}`,
        agent ? { agent } : { headers: { Connection: 'close' } },
        res => {
          let body = '';
          res.on('data', chunk => (body += chunk));
          res.on('end', () =>
            resolve({ status: res.statusCode || 0, headers: res.headers, body }),
          );
        },
      )
      .on('error', reject);
  });

let entered = 0;
let releaseBarrier: () => void;
const barrier = () =>
  new Promise<void>(resolve => {
    releaseBarrier = resolve;
  });

@Controller()
class ProbeController {
  @Get('gated')
  async gated() {
    entered++;
    await barrier();
    return { entered, handled: true };
  }

  @Get('notfound')
  async notFound() {
    throw new NotFoundException({ custom: 'body' });
  }
}

@Module({ controllers: [ProbeController] })
class ProbeModule {}

describe('graceful shutdown boundary probe', () => {
  let app: INestApplication;

  beforeEach(async () => {
    entered = 0;
    app = await NestFactory.create<NestFastifyApplication>(
      ProbeModule,
      new FastifyAdapter(),
      { return503OnClosing: true, logger: false },
    );
    await app.listen(0);
  });

  afterEach(async () => {
    releaseBarrier?.();
    try {
      await app.close();
    } catch {}
  });

  it('classifies the boundary deterministically: entered=200, post-close=503', async () => {
    const port = app.getHttpServer().address().port;
    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });

    // First request enters the handler and parks at the barrier.
    const first = rawRequest(port, '/gated', agent);
    await new Promise(r => setTimeout(r, 100));
